arguments.command:
python3 -c "
import json
d = json.load(open('measurements.json'))
def show(x, indent=0, maxlist=6):
    pad = '  '*indent
    if isinstance(x, dict):
        for k, v in x.items():
            if isinstance(v, (dict, list)):
                print(f'{pad}{k}: ({type(v).__name__}, len={len(v)})')
                show(v, indent+1)
            else:
                print(f'{pad}{k}: {v!r}')
    elif isinstance(x, list):
        if len(x) and all(isinstance(e,(int,float)) for e in x):
            print(f'{pad}[numbers] len={len(x)} first={x[:maxlist]} last={x[-3:]}')
        else:
            for i, e in enumerate(x[:maxlist]):
                print(f'{pad}[{i}]:')
                show(e, indent+1)
            if len(x) > maxlist: print(f'{pad}... ({len(x)} items)')
show(d)
"

